draw:
var Z = Math.round(p.Z);
var ni = Math.round(p.ni);
var nf = Math.round(p.nf);
if (nf >= ni) { nf = ni - 1; }
if (nf < 1) { nf = 1; }
var R = 13.6 * Z * Z;
var NMAX = 10;
var padT = 20, padB = 22;
var Emin = -R;
function Y(e) { return H - padB - (e - Emin) / (0 - Emin) * (H - padT - padB); }
var xL = 46, xR = W * 0.60;
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textBaseline = "middle";

// zero line
ctx.textAlign = "right";
ctx.strokeStyle = C.rule;
ctx.setLineDash([2, 4]);
ctx.beginPath();
ctx.moveTo(xL, Y(0));
ctx.lineTo(W - 8, Y(0));
ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.rule;
ctx.fillText("E = 0  (ionised)", W - 10, Y(0) - 10);

// levels
var n;
for (n = 1; n <= NMAX; n++) {
  var E = -R / (n * n);
  var y = Y(E);
  var hit = (n === ni || n === nf);
  ctx.strokeStyle = hit ? C.accent : C.faint;
  ctx.lineWidth = hit ? 2 : 1;
  ctx.beginPath();
  ctx.moveTo(xL, y);
  ctx.lineTo(xR, y);
  ctx.stroke();
  if (n <= 5 || hit) {
    ctx.fillStyle = hit ? C.accent : C.faint;
    ctx.textAlign = "right";
    ctx.fillText("n=" + n, xL - 5, y);
    ctx.textAlign = "left";
    ctx.fillStyle = hit ? C.accent : C.faint;
    ctx.fillText(E.toFixed(2) + " eV", xR + 6, y);
  }
}
ctx.lineWidth = 1;

// transition arrow
var yi = Y(-R / (ni * ni)), yf = Y(-R / (nf * nf));
var ax = xL + (xR - xL) * 0.35;
ctx.strokeStyle = C.figure;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(ax, yi);
ctx.lineTo(ax, yf);
ctx.stroke();
ctx.beginPath();
ctx.moveTo(ax, yf);
ctx.lineTo(ax - 4, yf - 8);
ctx.lineTo(ax + 4, yf - 8);
ctx.closePath();
ctx.fillStyle = C.figure;
ctx.fill();
ctx.lineWidth = 1;

var dE = R * (1 / (nf * nf) - 1 / (ni * ni));
var lam = 1240 / dE;

// emitted photon, a wave travelling right
var span = W - (xR + 70);
if (span < 40) { span = 40; }
var x0 = xR + 62;
var travel = (t % 2.2) / 2.2;
var yph = (yi + yf) / 2;
ctx.strokeStyle = C.figure;
ctx.beginPath();
var s;
var lead = x0 + travel * span;
for (s = 0; s <= 46; s += 1) {
  var xx = lead - 46 + s;
  if (xx < x0) { continue; }
  var yy = yph + 6 * Math.sin(s * 0.7);
  if (xx === lead - 46 + s && s === 0) { ctx.moveTo(xx, yy); } else { ctx.lineTo(xx, yy); }
}
ctx.stroke();
ctx.fillStyle = C.figure;
ctx.textAlign = "left";
ctx.fillText("photon", x0, yph + 20);

ctx.fillStyle = C.ink;
ctx.textAlign = "center";
ctx.fillText("n=" + ni + " to n=" + nf, (xL + xR) / 2, padT - 8 + 6);

out.note = "Z = " + Z + ", n = " + ni + " to " + nf + ":  dE = " + dE.toFixed(3) + " eV,  lambda = 1240/dE = " + (lam < 10000 ? lam.toFixed(1) + " nm" : lam.toExponential(2) + " nm");
